<?php require_once __DIR__.'/includes/bootstrap.php';require_role('customer');header('Content-Type: application/json');$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$q=db()->prepare('SELECT * FROM queue_tickets WHERE id=? AND customer_user_id=?');$q->execute([$id,$_SESSION['user_id']]);$t=$q->fetch();if(!$t){http_response_code(404);echo json_encode(['error'=>'Not found']);exit;}$ahead=0;if(in_array($t['status'],['WAITING','CALLED'])){$p=db()->prepare("SELECT COUNT(*) FROM queue_tickets WHERE business_id=? AND ticket_date=? AND daily_number<? AND status IN ('WAITING','CALLED')");$p->execute([$t['business_id'],$t['ticket_date'],$t['daily_number']]);$ahead=(int)$p->fetchColumn();}echo json_encode(['status'=>$t['status'],'ahead'=>$ahead]);